9	// Directly submitted Input records must satisfy the same effective-value
10	// rules as single Register calls and parsed file records: the three text
11	// fields are non-empty valid UTF-8 and quantity is positive — regardless of
12	// whether the batch id is new, already stored or seen earlier in the same
13	// submission, so the validity check can never be skipped by the create,
14	// duplicate-confirmation or conflict branch.
15	func TestImportRejectsInvalidDirectRecords(t *testing.T) {
16		valid := func() Input { return Input{Batch: "B1", Product: "P-7", Quantity: 10, Unit: "kg"} }
17	
18		cases := []struct {
19			name      string
20			mutate    func(*Input)
21			wantField string
22		}{
23			{"empty batch", func(in *Input) { in.Batch = "" }, "batch"},
24			{"empty product", func(in *Input) { in.Product = "" }, "product"},
25			{"empty unit", func(in *Input) { in.Unit = "" }, "unit"},
26			{"quantity zero", func(in *Input) { in.Quantity = 0 }, "quantity"},
27			{"quantity negative", func(in *Input) { in.Quantity = -4 }, "quantity"},
28		}
29	
30		// Each scenario places the offending record where, before the fix, a
31		// different branch used to accept it or classify it as a conflict: a
32		// brand-new id, an id already stored (an empty text field would have
33		// looked like a registry conflict), and an id introduced earlier in the
34		// same submission. prepare aligns the record with the stored/earlier id
35		// before the mutation empties the batch field itself.
36		scenarios := []struct {
37			name    string
38			reg     []Batch
39			pos     int
40			prepare func(in *Input)
41			prefix  func() []Input // records preceding the bad one
42		}{
43			{
44				name:    "new id",
45				pos:     1,
46				prepare: func(in *Input) {},
47				prefix:  func() []Input { return nil },
48			},
49			{
50				name: "id already registered",
51				reg:  []Batch{{Batch: "B1", Product: "P-7", Quantity: 10, Unit: "kg"}},
52				pos:  2,
53				prepare: func(in *Input) {
54					in.Batch = "B1"
55					in.Product = "P-7"
56					in.Unit = "kg"
57				},
58				// Record 1 confirms the stored duplicate before record 2 fails.
59				prefix: func() []Input {
60					return []Input{{Batch: "B1", Product: "P-7", Quantity: 10, Unit: "kg"}}
61				},
62			},
63			{
64				name:    "id seen earlier in this submission",
65				pos:     2,
66				prepare: func(in *Input) { in.Batch = "B1" },
67				prefix: func() []Input {
68					return []Input{{Batch: "B1", Product: "P-7", Quantity: 10, Unit: "kg"}}
69				},
70			},
71		}
72	
73		for _, sc := range scenarios {
74			t.Run(sc.name, func(t *testing.T) {
75				for _, tc := range cases {
76					t.Run(tc.name, func(t *testing.T) {
77						reg := &Registry{Version: FormatVersion, Batches: append([]Batch(nil), sc.reg...)}
78						bad := valid()
79						sc.prepare(&bad)
80						tc.mutate(&bad)
81						inputs := append(sc.prefix(), bad)
82	
83						results, err := Import(reg, inputs)
84						var re *ManifestRecordError
85						if !errors.As(err, &re) {
86							t.Fatalf("got %v, want ManifestRecordError", err)
87						}
88						var ce *ManifestConflictError
89						if errors.As(err, &ce) {
90							t.Fatalf("invalid record must not be reported as a conflict: %v", err)
91						}
92						if results != nil {
93							t.Fatalf("failed import must report no results, got %+v", results)
94						}
95						if re.Position != sc.pos {
96							t.Errorf("position=%d, want %d", re.Position, sc.pos)
97						}
98						if !strings.Contains(re.Reason, tc.wantField) {
99							t.Errorf("reason %q must name field %q", re.Reason, tc.wantField)
100						}
101						// Registry keeps exactly its pre-import content.
102						if len(reg.Batches) != len(sc.reg) {
103							t.Fatalf("rejected import mutated the registry: %+v", reg.Batches)
104						}
105						for i, b := range sc.reg {
106							if reg.Batches[i] != b {
107								t.Fatalf("rejected import mutated record %d: %+v", i+1, reg.Batches[i])
108							}
109						}
110					})
111				}
112			})
113		}
114	}
115	
116	// A late invalid record fails the whole submission even when the earlier
117	// records have already resolved as creates, same-submission duplicates and
118	// stored duplicates: nothing new may remain and the caller gets no partial
119	// result.
120	func TestImportLateInvalidRecordFailsWholeSubmission(t *testing.T) {
121		original := []Batch{{Batch: "OLD", Product: "P-1", Quantity: 3, Unit: "kg"}}
122		reg := &Registry{Version: FormatVersion, Batches: append([]Batch(nil), original...)}
123		results, err := Import(reg, []Input{
124			{Batch: "NEW1", Product: "P-2", Quantity: 10, Unit: "box"}, // would create
125			{Batch: "NEW1", Product: "P-2", Quantity: 10, Unit: "box"}, // same-submission duplicate
126			{Batch: "OLD", Product: "P-1", Quantity: 3, Unit: "kg"},    // stored duplicate
127			{Batch: "NEW2", Product: "P-3", Quantity: 1, Unit: "m"},    // would create
128			{Batch: "NEW3", Product: "P-4", Quantity: 1, Unit: ""},     // invalid
129		})
130		var re *ManifestRecordError
131		if !errors.As(err, &re) {
132			t.Fatalf("got %v, want ManifestRecordError", err)
133		}
134		if re.Position != 5 || re.Batch != "NEW3" {
135			t.Fatalf("unexpected error position/batch: %+v", re)
136		}
137		if !strings.Contains(re.Reason, `"unit"`) {
138			t.Fatalf("reason must name field %q: %s", "unit", re.Reason)
139		}
140		if results != nil {
141			t.Fatalf("failed import must report no results, got %+v", results)
142		}
143		if len(reg.Batches) != 1 || reg.Batches[0] != original[0] {
144			t.Fatalf("rejected import left new batches in the registry: %+v", reg.Batches)
145		}
146	}
147	
148	// The batch id is cited only when the batch field itself is non-empty and
149	// valid UTF-8; an empty or malformed id is never invented or replaced. The
150	// offending field always rides in the reason text.
151	func TestImportInvalidRecordBatchAttachment(t *testing.T) {
152		fffd := string(rune(0xfffd))
153		cases := []struct {
154			name            string
155			in              Input
156			wantBatch       string
157			wantReasonField string
158		}{
159			{"empty batch", Input{Batch: "", Product: "P", Quantity: 1, Unit: "kg"}, "", "batch"},
160			{"invalid utf8 batch", Input{Batch: "B-\xff", Product: "P", Quantity: 1, Unit: "kg"}, "", "batch"},
161			{"empty product names batch", Input{Batch: "B7", Product: "", Quantity: 1, Unit: "kg"}, "B7", "product"},
162			{"empty unit names batch", Input{Batch: "B7", Product: "P", Quantity: 1, Unit: ""}, "B7", "unit"},
163			{"zero quantity names batch", Input{Batch: "B7", Product: "P", Quantity: 0, Unit: "kg"}, "B7", "quantity"},
164			{"bad product bytes names valid batch", Input{Batch: "B7", Product: "P\xff", Quantity: 1, Unit: "kg"}, "B7", "product"},
165			{"whitespace batch cited verbatim", Input{Batch: " B ", Product: "P", Quantity: 0, Unit: "kg"}, " B ", "quantity"},
166			{"genuine replacement char is a valid id", Input{Batch: fffd, Product: "P", Quantity: 0, Unit: "kg"}, fffd, "quantity"},
167		}
168		for _, tc := range cases {
169			t.Run(tc.name, func(t *testing.T) {
170				reg := &Registry{Version: FormatVersion}
171				_, err := Import(reg, []Input{tc.in})
172				var re *ManifestRecordError
173				if !errors.As(err, &re) {
174					t.Fatalf("got %v, want ManifestRecordError", err)
175				}
176				if re.Position != 1 {
177					t.Errorf("position=%d, want 1", re.Position)
178				}
179				if re.Batch != tc.wantBatch {
180					t.Errorf("batch=%q, want %q", re.Batch, tc.wantBatch)
181				}
182				if !strings.Contains(re.Reason, tc.wantReasonField) {
183					t.Errorf("reason %q must name field %q", re.Reason, tc.wantReasonField)
184				}
185				if tc.wantBatch == "" && strings.Contains(err.Error(), "(batch \"") {
186					t.Errorf("error must not cite a batch id: %v", err)
187				}
188				if tc.wantBatch != "" && !strings.Contains(err.Error(), `(batch "`+tc.wantBatch+`")`) {
189					t.Errorf("error must cite batch %q verbatim: %v", tc.wantBatch, err)
190				}
191				if len(reg.Batches) != 0 {
192					t.Fatalf("rejected import appended records: %+v", reg.Batches)
193				}
194			})
195		}
196	}
197	
198	// Direct submissions keep text verbatim: no trimming and no case folding.
199	// Edge and interior whitespace stay part of the value, so ids that differ
200	// only by such characters are different batches.
201	func TestImportKeepsDirectTextVerbatim(t *testing.T) {
202		reg := &Registry{Version: FormatVersion}
203		inputs := []Input{
204			{Batch: " B1 ", Product: " P 7 ", Quantity: 1, Unit: " kg "},
205			{Batch: " B1 ", Product: " P 7 ", Quantity: 1, Unit: " kg "}, // verbatim repeat -> duplicate
206			{Batch: "B1", Product: "P7", Quantity: 1, Unit: "kg"},        // distinct id and values
207		}
208		out, err := Import(reg, inputs)
209		if err != nil {
210			t.Fatal(err)
211		}
212		if len(out) != 3 || !out[0].Created || out[1].Created || !out[2].Created {
213			t.Fatalf("unexpected outcomes: %+v", out)
214		}
215		want := []Batch{
216			{Batch: " B1 ", Product: " P 7 ", Quantity: 1, Unit: " kg "},
217			{Batch: "B1", Product: "P7", Quantity: 1, Unit: "kg"},
218		}
219		for i, b := range want {
220			if reg.Batches[i] != b {
221				t.Errorf("stored record %d = %+v, want %+v", i+1, reg.Batches[i], b)
222			}
223		}
224	}
225	
226	// Whitespace-only text is a legal non-empty direct value: the no-trimming
227	// rule belongs to the direct path, and such a record is accepted the same
228	// way it would be through the single-record Register entry.
229	func TestImportAcceptsWhitespaceOnlyDirectText(t *testing.T) {
230		reg := &Registry{Version: FormatVersion}
231		in := Input{Batch: " ", Product: "\t", Quantity: 1, Unit: "\n"}
232		out, err := Import(reg, []Input{in, in})
233		if err != nil {
234			t.Fatalf("whitespace-only text is non-empty and must be accepted: %v", err)
235		}
236		if !out[0].Created || out[1].Created {
237			t.Fatalf("unexpected outcomes: %+v", out)
238		}
239		if len(reg.Batches) != 1 || reg.Batches[0].Batch != " " || reg.Batches[0].Product != "\t" || reg.Batches[0].Unit != "\n" {
240			t.Fatalf("text not kept verbatim: %+v", reg.Batches)
241		}
242	}
