15	func writeFile(t *testing.T, path, content string) {
16		t.Helper()
17		if err := os.MkdirAll(filepath.Dir(path), 0o755); err != nil {
18			t.Fatal(err)
19		}
20		if err := os.WriteFile(path, []byte(content), 0o644); err != nil {
21			t.Fatal(err)
22		}
23	}
24	
25	type importOutput struct {
26		Results []struct {
27			Batch    string `json:"batch"`
28			Product  string `json:"product"`
29			Quantity int64  `json:"quantity"`
30			Unit     string `json:"unit"`
31			Status   string `json:"status"`
32		} `json:"results"`
33	}
34	
35	func TestBatchImportCLICreatesRegistry(t *testing.T) {
36		dir := t.TempDir()
37		registry := filepath.Join(dir, "nested", "reg.json")
38		manifest := filepath.Join(dir, "in.json")
39		writeFile(t, manifest, `[
40	  {"batch": " B1 ", "product": "P-7", "quantity": 120, "unit": "kg"},
41	  {"batch": "B1", "product": "P-7", "quantity": 120, "unit": "kg"},
42	  {"batch": "B2", "product": "P-8", "quantity": 1, "unit": "box"}
43	]`)
44	
45		var stdout bytes.Buffer
46		if err := runBatchImport([]string{"--registry", registry, "--input", manifest}, &stdout); err != nil {
47			t.Fatalf("import failed: %v", err)
48		}
49		var out importOutput
50		if err := json.Unmarshal(bytes.TrimSpace(stdout.Bytes()), &out); err != nil {
51			t.Fatalf("stdout is not the expected JSON: %v (%q)", err, stdout.String())
52		}
53		wantStatus := []string{"created", "duplicate", "created"}
54		if len(out.Results) != len(wantStatus) {
55			t.Fatalf("got %d results", len(out.Results))
56		}
57		for i, want := range wantStatus {
58			if out.Results[i].Status != want {
59				t.Errorf("result %d status = %q, want %q", i+1, out.Results[i].Status, want)
