  {"batch": "OTHER", "product": "P-8", "quantity": 1, "unit": "box"},
  {"batch": "B1", "product": "P-7", "quantity": 10, "unit": "kg"},
  {"batch": "OLD", "product": "P0", "quantity": 7, "unit": "box"},
